// Station meteo temps reel - solution complete (ESP32 / Arduino + FreeRTOS)

#include <Arduino.h>

typedef struct {
  float temperature;
  float humidite;
  uint32_t sequence;
  uint32_t tick;
  bool valide;
} Mesure;

QueueHandle_t fileMesures = NULL;
SemaphoreHandle_t mutexSerial = NULL;
uint32_t sequence = 0;

void ecrireLog(const char *message) {
  if (xSemaphoreTake(mutexSerial, pdMS_TO_TICKS(50)) == pdTRUE) {
    Serial.println(message);
    xSemaphoreGive(mutexSerial);
  } else {
    Serial.println("trace perdue : port serie occupe");
  }
}

Mesure lireEtFiltrer() {
  Mesure m;
  m.temperature = 20.0f + (float)(millis() % 1000) / 100.0f;
  m.humidite = 50.0f + (float)(millis() % 500) / 100.0f;
  m.sequence = ++sequence;
  m.valide = true;
  if (m.temperature < -40.0f || m.temperature > 85.0f) m.valide = false;
  return m;
}

void tacheCapteur(void *parametre) {
  TickType_t reveil = xTaskGetTickCount();
  Mesure m;
  for (;;) {
    m = lireEtFiltrer();
    m.tick = xTaskGetTickCount();
    if (m.valide) xQueueOverwrite(fileMesures, &m);
    xTaskDelayUntil(&reveil, pdMS_TO_TICKS(1000));
  }
}

void tacheAfficheur(void *parametre) {
  TickType_t reveil = xTaskGetTickCount();
  Mesure copie;
  for (;;) {
    if (xQueuePeek(fileMesures, &copie, 0) == pdTRUE) {
      char ligne[64];
      snprintf(ligne, sizeof(ligne), "T=%.2f C  H=%.1f %%  seq=%lu",
               copie.temperature, copie.humidite,
               (unsigned long)copie.sequence);
      ecrireLog(ligne);
    }
    xTaskDelayUntil(&reveil, pdMS_TO_TICKS(250));
  }
}

void tacheReseau(void *parametre) {
  TickType_t reveil = xTaskGetTickCount();
  Mesure aPublier;
  for (;;) {
    // maintenirLiaisonWifi() doit lui-meme etre borne dans le temps
    if (xQueueReceive(fileMesures, &aPublier, pdMS_TO_TICKS(100)) == pdTRUE) {
      if (aPublier.valide) {
        // publierMQTT(aPublier) : 50 ms en temps normal, 2 s si relance
      }
    }
    xTaskDelayUntil(&reveil, pdMS_TO_TICKS(10000));
  }
}

void afficherDiagnostic(const char *nom) {
  UBaseType_t libre = uxTaskGetStackHighWaterMark(NULL);
  char ligne[64];
  snprintf(ligne, sizeof(ligne), "%s : %u octets de pile libres",
           nom, (unsigned)libre);
  ecrireLog(ligne);
}

void setup() {
  Serial.begin(115200);

  fileMesures = xQueueCreate(1, sizeof(Mesure));
  mutexSerial = xSemaphoreCreateMutex();
  if (fileMesures == NULL || mutexSerial == NULL) {
    Serial.println("creation des objets de synchro impossible");
    while (true) delay(1000);
  }

  BaseType_t ok;
  ok = xTaskCreatePinnedToCore(tacheCapteur, "capteur", 4096, NULL, 3, NULL, 1);
  if (ok != pdPASS) Serial.println("echec creation tache capteur");
  ok = xTaskCreatePinnedToCore(tacheAfficheur, "ecran", 4096, NULL, 2, NULL, 1);
  if (ok != pdPASS) Serial.println("echec creation tache ecran");
  ok = xTaskCreatePinnedToCore(tacheReseau, "reseau", 6144, NULL, 2, NULL, 1);
  if (ok != pdPASS) Serial.println("echec creation tache reseau");

  ecrireLog("station meteo demarree en trois taches");
}

void loop() {
  if (Serial.available()) {
    String commande = Serial.readStringUntil('\n');
    commande.trim();
    if (commande == "etat") {
      afficherDiagnostic("service");
    }
  }
  vTaskDelay(pdMS_TO_TICKS(50));
}
